F2 = [['负载消失', '利用率 → 1%'], ['稳定窗口 30 秒', '取窗口内最大的建议'], ['6 → 2', '58 秒'], ['2 → 1', '73 秒']]
F3 = [['tol-in 52%', '比值 1.04'], ['在 ±10% 容忍区内', '2 个副本不动'], ['tol-out 70%', '比值 1.4'], ['2 → 3 → 5', '']]
